#include <iostream>
using namespace std;

const int MAXN = 100005;
int out[MAXN], st[MAXN];

int main() {
    int n;
    if (!(cin >> n)) return 0;
    for (int i = 0; i < n; i++) cin >> out[i];

    int top = -1, j = 0;
    for (int i = 1; i <= n; i++) {
        st[++top] = i;                       // 入栈
        while (top >= 0 && st[top] == out[j]) {   // 能弹就弹
            top--;
            j++;
        }
    }
    cout << (top < 0 && j == n ? "YES\n" : "NO\n");
    return 0;
}
